import{c as t,Q as e,j as r,m as i}from"./chunks/framework.BnKG8mJY.js";const p=JSON.parse('{"title":"Dashboard Overview","description":"","frontmatter":{"title":"Dashboard Overview","outline":"deep"},"headers":[],"relativePath":"guide/dashboard.md","filePath":"guide/dashboard.md"}'),n={name:"guide/dashboard.md"};function d(l,a,o,s,h,u){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="dashboard-monitoring" tabindex="-1">Dashboard &amp; Monitoring <a class="header-anchor" href="#dashboard-monitoring" aria-label="Permalink to &quot;Dashboard &amp; Monitoring&quot;">​</a></h1><p>Dokumentasi untuk semua halaman di menu Dashboard: Home, Schedule Pengiriman, Monitoring Kendaraan, Lokasi Truk, dan KM Bulanan Truk.</p><hr><h2 id="home-dashboard-utama" tabindex="-1">Home (Dashboard Utama) <a class="header-anchor" href="#home-dashboard-utama" aria-label="Permalink to &quot;Home (Dashboard Utama)&quot;">​</a></h2><p><strong>Path:</strong> <code>/</code></p><p>Halaman utama setelah login. Menampilkan ringkasan performa operasional dan finansial.</p><h3 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h3><p>Dashboard terdiri dari 3 section collapsible + 1 section tetap:</p><table tabindex="0"><thead><tr><th>Section</th><th style="text-align:center;">Collapsible</th><th>Deskripsi</th></tr></thead><tbody><tr><td>Ringkasan Dashboard</td><td style="text-align:center;">✅</td><td>Metrik utama, grafik, dan event</td></tr><tr><td>Expiry Alerts</td><td style="text-align:center;">❌</td><td>Peringatan dokumen expired</td></tr><tr><td>Statistics Sales Cost</td><td style="text-align:center;">✅</td><td>Grafik tren Sales Cost</td></tr><tr><td>Statistics Subcontractor Cost</td><td style="text-align:center;">✅</td><td>Grafik tren Subcontractor</td></tr></tbody></table><h3 id="ringkasan-dashboard" tabindex="-1">Ringkasan Dashboard <a class="header-anchor" href="#ringkasan-dashboard" aria-label="Permalink to &quot;Ringkasan Dashboard&quot;">​</a></h3><p>Berisi komponen-komponen berikut:</p><h4 id="sales-cost-subcontractor-metrics" tabindex="-1">Sales Cost &amp; Subcontractor Metrics <a class="header-anchor" href="#sales-cost-subcontractor-metrics" aria-label="Permalink to &quot;Sales Cost &amp; Subcontractor Metrics&quot;">​</a></h4><p>Dua card metrik yang menampilkan jumlah transaksi bulan terpilih:</p><ul><li><strong>Sales Cost</strong> — jumlah transaksi Sales Cost + indikator naik/turun vs bulan lalu</li><li><strong>Subcontractor</strong> — jumlah transaksi Subcontractor + indikator naik/turun vs bulan lalu</li></ul><p>Masing-masing punya filter bulan/tahun sendiri.</p><h4 id="detail-sales-cost-monthly" tabindex="-1">Detail Sales Cost (Monthly) <a class="header-anchor" href="#detail-sales-cost-monthly" aria-label="Permalink to &quot;Detail Sales Cost (Monthly)&quot;">​</a></h4><p>Ringkasan angka kunci bulan terpilih:</p><ul><li><strong>Sales</strong> — total pendapatan</li><li><strong>Total Cost</strong> — total biaya operasional</li><li><strong>Gross Profit</strong> — selisih Sales − Total Cost</li><li>Indikator persentase perubahan vs bulan sebelumnya</li></ul><p>Filter: bulan + tahun.</p><h4 id="monthly-sales-transaction" tabindex="-1">Monthly Sales Transaction <a class="header-anchor" href="#monthly-sales-transaction" aria-label="Permalink to &quot;Monthly Sales Transaction&quot;">​</a></h4><p>Grafik bar chart menampilkan volume transaksi Sales Cost dan Subcontractor per bulan dalam satu tahun.</p><p>Filter: tahun.</p><h4 id="truck-transaction-average" tabindex="-1">Truck Transaction Average <a class="header-anchor" href="#truck-transaction-average" aria-label="Permalink to &quot;Truck Transaction Average&quot;">​</a></h4><p>Menampilkan rata-rata penggunaan truck berdasarkan Delivery Order per bulan:</p><ul><li>Persentase loading per truck (rumus: <code>transaksi / 21 hari kerja × 100</code>)</li><li>Tabel truck dengan jumlah transaksi dan persentase</li><li>Filter: bulan + tahun</li></ul><h4 id="calendar-event-list" tabindex="-1">Calendar Event List <a class="header-anchor" href="#calendar-event-list" aria-label="Permalink to &quot;Calendar Event List&quot;">​</a></h4><p>Daftar event kalender terbaru:</p><ul><li>Kolom: Event, Date/Time, Created by</li><li>Filter periode tanggal</li><li>Tombol <strong>See All</strong> → halaman Calendar</li></ul><h3 id="expiry-alerts" tabindex="-1">Expiry Alerts <a class="header-anchor" href="#expiry-alerts" aria-label="Permalink to &quot;Expiry Alerts&quot;">​</a></h3><p>Peringatan dokumen kendaraan/supir yang mendekati atau sudah expired:</p><ul><li>Badge <strong>Expired</strong> (merah) — sudah lewat masa berlaku</li><li>Badge <strong>Warning</strong> (kuning) — mendekati expired (H-30)</li><li>Tabel: nama dokumen, kendaraan/supir, tanggal expired</li></ul><h3 id="statistics-sales-cost" tabindex="-1">Statistics Sales Cost <a class="header-anchor" href="#statistics-sales-cost" aria-label="Permalink to &quot;Statistics Sales Cost&quot;">​</a></h3><p>Grafik area chart dengan 3 series:</p><ul><li><strong>Sales</strong> (biru)</li><li><strong>Total Cost</strong> (orange)</li><li><strong>Gross Profit</strong> (hijau)</li></ul><p>Filter periode: <strong>Monthly</strong> | <strong>Quarterly</strong> | <strong>Annually</strong> + filter tahun.</p><h3 id="statistics-subcontractor-cost" tabindex="-1">Statistics Subcontractor Cost <a class="header-anchor" href="#statistics-subcontractor-cost" aria-label="Permalink to &quot;Statistics Subcontractor Cost&quot;">​</a></h3><p>Format identik dengan Statistics Sales Cost, tapi data dari transaksi Subcontractor.</p><h3 id="interaksi" tabindex="-1">Interaksi <a class="header-anchor" href="#interaksi" aria-label="Permalink to &quot;Interaksi&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aksi</th><th>Fungsi</th></tr></thead><tbody><tr><td>Collapse/Expand</td><td>Klik panah di header section</td></tr><tr><td>Collapse All / Expand All</td><td>Tombol di header Ringkasan</td></tr><tr><td>Print Ringkasan</td><td>Cetak section Ringkasan (filter bulan/tahun)</td></tr></tbody></table><p>State collapse/expand tersimpan di localStorage.</p><hr><h2 id="schedule-pengiriman" tabindex="-1">Schedule Pengiriman <a class="header-anchor" href="#schedule-pengiriman" aria-label="Permalink to &quot;Schedule Pengiriman&quot;">​</a></h2><p><strong>Path:</strong> <code>/schedule-pengiriman</code></p><p>Halaman jadwal pengiriman. Satu-satunya halaman yang bisa diakses oleh role <strong>CS</strong>.</p><h3 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Deskripsi</th></tr></thead><tbody><tr><td>Tanggal Delivery Order</td><td>Filter berdasarkan tanggal kirim</td></tr><tr><td>Tanggal Arrival Order</td><td>Filter berdasarkan tanggal tiba</td></tr><tr><td>Kata Kunci</td><td>Cari: No Police, Customer, Driver, atau No DN</td></tr></tbody></table><p>Tombol: <strong>Tampilkan</strong> (apply filter), <strong>Reset</strong> (clear filter).</p><h3 id="tabel-utama" tabindex="-1">Tabel Utama <a class="header-anchor" href="#tabel-utama" aria-label="Permalink to &quot;Tabel Utama&quot;">​</a></h3><p>Kolom (semua sortable):</p><table tabindex="0"><thead><tr><th>Kolom</th><th>Deskripsi</th></tr></thead><tbody><tr><td>Delivery Order</td><td>Tanggal pengiriman</td></tr><tr><td>No. Police</td><td>Plat nomor kendaraan</td></tr><tr><td>Driver</td><td>Nama supir</td></tr><tr><td>Customer</td><td>Nama pelanggan</td></tr><tr><td>Rute</td><td>Area/rute pengiriman</td></tr><tr><td>Arrival Order</td><td>Tanggal tiba</td></tr><tr><td>No. PO</td><td>Nomor Purchase Order</td></tr><tr><td>Jenis Pengiriman</td><td>Tipe pengiriman</td></tr><tr><td>DN</td><td>Jumlah Delivery Note</td></tr><tr><td>Trip</td><td>Nomor trip</td></tr></tbody></table><h3 id="detail-dn-expandable-row" tabindex="-1">Detail DN (Expandable Row) <a class="header-anchor" href="#detail-dn-expandable-row" aria-label="Permalink to &quot;Detail DN (Expandable Row)&quot;">​</a></h3><p>Klik baris atau tombol expand untuk melihat detail DN:</p><table tabindex="0"><thead><tr><th>Kolom</th><th>Deskripsi</th></tr></thead><tbody><tr><td>No. DN</td><td>Nomor Delivery Note</td></tr><tr><td>Pickup</td><td>Alamat pickup</td></tr><tr><td>Drop</td><td>Alamat drop</td></tr><tr><td>Qty</td><td>Jumlah barang</td></tr><tr><td>PKG</td><td>Packaging</td></tr><tr><td>G.W</td><td>Gross Weight</td></tr><tr><td>No. Container</td><td>Nomor container</td></tr><tr><td>No. Aju</td><td>Nomor AJU</td></tr><tr><td>Remarks</td><td>Catatan</td></tr></tbody></table><h3 id="fitur-lain" tabindex="-1">Fitur Lain <a class="header-anchor" href="#fitur-lain" aria-label="Permalink to &quot;Fitur Lain&quot;">​</a></h3><ul><li>Expand All / Collapse All (tombol di header tabel)</li><li>Pagination dengan pilihan rows per page</li><li>Total transaksi ditampilkan</li></ul><hr><h2 id="monitoring-kendaraan" tabindex="-1">Monitoring Kendaraan <a class="header-anchor" href="#monitoring-kendaraan" aria-label="Permalink to &quot;Monitoring Kendaraan&quot;">​</a></h2><p><strong>Path:</strong> <code>/monitoring-kendaraan</code></p><p>Halaman untuk memantau status seluruh armada berdasarkan aktivitas operasional (transaksi/repair/idle).</p><h3 id="header" tabindex="-1">Header <a class="header-anchor" href="#header" aria-label="Permalink to &quot;Header&quot;">​</a></h3><ul><li>Judul: &quot;Pantau status kendaraan berdasarkan transaksi aktif dan repair&quot;</li><li>Tombol <strong>Buka Peta</strong> → link ke Lokasi Truk (<code>/truck-locations</code>)</li><li>Search: plat / kendaraan / driver</li><li>Tombol: <strong>Tampilkan</strong>, <strong>Reset</strong></li></ul><h3 id="summary-cards-clickable-filter" tabindex="-1">Summary Cards (Clickable Filter) <a class="header-anchor" href="#summary-cards-clickable-filter" aria-label="Permalink to &quot;Summary Cards (Clickable Filter)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Card</th><th>Deskripsi</th></tr></thead><tbody><tr><td>Total Kendaraan</td><td>Jumlah seluruh armada aktif</td></tr><tr><td>Transaksi</td><td>Kendaraan sedang dalam pengiriman</td></tr><tr><td>Repair</td><td>Kendaraan sedang dalam perbaikan</td></tr><tr><td>Idle</td><td>Kendaraan tidak sedang digunakan</td></tr></tbody></table><p>Klik card untuk filter tampilan ke kategori tersebut.</p><h3 id="daftar-kendaraan" tabindex="-1">Daftar Kendaraan <a class="header-anchor" href="#daftar-kendaraan" aria-label="Permalink to &quot;Daftar Kendaraan&quot;">​</a></h3><p>Ditampilkan dalam format card per kendaraan:</p><ul><li>Plat nomor dan jenis kendaraan</li><li>Nama driver</li><li>Rute pengiriman (jika transaksi)</li><li>Tanggal delivery dan arrival</li><li>Durasi pengiriman</li></ul><p>Dikelompokkan berdasarkan status: Transaksi, Repair, Idle.</p><hr><h2 id="lokasi-truk-gps-map" tabindex="-1">Lokasi Truk (GPS Map) <a class="header-anchor" href="#lokasi-truk-gps-map" aria-label="Permalink to &quot;Lokasi Truk (GPS Map)&quot;">​</a></h2><p><strong>Path:</strong> <code>/truck-locations</code></p><p>Peta live yang menampilkan posisi seluruh armada secara real-time menggunakan data Wialon GPS.</p><h3 id="header-1" tabindex="-1">Header <a class="header-anchor" href="#header-1" aria-label="Permalink to &quot;Header&quot;">​</a></h3><ul><li>Judul: &quot;Lokasi Truk&quot;</li><li>Subtitle: &quot;Peta live Wialon dengan inspector kendaraan dan daftar armada yang selalu sinkron&quot;</li><li>Info: jumlah armada + waktu sinkron terakhir</li><li>Tombol <strong>Monitoring</strong> → link ke Monitoring Kendaraan</li><li>Tombol <strong>Refresh Sekarang</strong> → refresh manual data GPS</li><li>Auto-refresh setiap <strong>30 detik</strong></li></ul><h3 id="layout-3-panel" tabindex="-1">Layout 3 Panel <a class="header-anchor" href="#layout-3-panel" aria-label="Permalink to &quot;Layout 3 Panel&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Panel</th><th>Posisi</th><th>Fungsi</th></tr></thead><tbody><tr><td>Peta (Leaflet)</td><td>Kiri</td><td>Map dengan marker per truck + clustering</td></tr><tr><td>Vehicle Detail</td><td>Tengah</td><td>Detail truck yang dipilih (hidden sampai dipilih)</td></tr><tr><td>Fleet List</td><td>Kanan</td><td>Daftar armada dengan search &amp; filter</td></tr></tbody></table><h3 id="gps-status-filter-chips" tabindex="-1">GPS Status Filter Chips <a class="header-anchor" href="#gps-status-filter-chips" aria-label="Permalink to &quot;GPS Status Filter Chips&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Filter</th><th>Warna</th><th>Arti</th></tr></thead><tbody><tr><td>All</td><td>—</td><td>Semua truck</td></tr><tr><td>Moving</td><td>Hijau</td><td>Kendaraan bergerak</td></tr><tr><td>Idle</td><td>Biru</td><td>Kendaraan diam tapi GPS aktif</td></tr><tr><td>Offline</td><td>Abu-abu</td><td>GPS tidak mengirim data</td></tr><tr><td>Belum Terhubung</td><td>Amber</td><td>Belum ada mapping Wialon atau belum ada posisi</td></tr></tbody></table><h3 id="vehicle-detail-panel-tengah" tabindex="-1">Vehicle Detail (Panel Tengah) <a class="header-anchor" href="#vehicle-detail-panel-tengah" aria-label="Permalink to &quot;Vehicle Detail (Panel Tengah)&quot;">​</a></h3><p>Muncul saat truck dipilih (klik marker atau klik di Fleet List):</p><table tabindex="0"><thead><tr><th>Info</th><th>Deskripsi</th></tr></thead><tbody><tr><td>Driver</td><td>Nama supir yang ditugaskan</td></tr><tr><td>Wialon Unit</td><td>ID unit di Wialon</td></tr><tr><td>Speed</td><td>Kecepatan saat ini</td></tr><tr><td>Last Update</td><td>Waktu GPS terakhir kirim data</td></tr><tr><td>Lokasi</td><td>Alamat (reverse geocoding via Geoapify)</td></tr><tr><td>Transaksi Aktif</td><td>Info pengiriman yang sedang berjalan</td></tr><tr><td>Repair Aktif</td><td>Info repair jika sedang dalam perbaikan</td></tr><tr><td>Transaksi Terakhir</td><td>Info pengiriman terakhir yang selesai</td></tr></tbody></table><h3 id="fleet-list-panel-kanan" tabindex="-1">Fleet List (Panel Kanan) <a class="header-anchor" href="#fleet-list-panel-kanan" aria-label="Permalink to &quot;Fleet List (Panel Kanan)&quot;">​</a></h3><ul><li>Daftar semua truck dengan badge status GPS</li><li>Search: plat, driver, unit ID, rute</li><li>Klik item → fokus marker di peta + buka Vehicle Detail</li><li>Scrollable dengan fixed height</li></ul><h3 id="marker-clustering" tabindex="-1">Marker Clustering <a class="header-anchor" href="#marker-clustering" aria-label="Permalink to &quot;Marker Clustering&quot;">​</a></h3><p>Truck yang berdekatan dikelompokkan dalam cluster:</p><ul><li>Warna cluster mengikuti status dominan (moving/idle/offline)</li><li>Klik cluster → zoom in</li><li>Popup cluster menampilkan summary status</li></ul><hr><h2 id="km-bulanan-truk" tabindex="-1">KM Bulanan Truk <a class="header-anchor" href="#km-bulanan-truk" aria-label="Permalink to &quot;KM Bulanan Truk&quot;">​</a></h2><p><strong>Path:</strong> <code>/truck-monthly-mileage</code></p><p>Rekap jarak tempuh bulanan per truck berdasarkan data trip Wialon.</p><h3 id="header-2" tabindex="-1">Header <a class="header-anchor" href="#header-2" aria-label="Permalink to &quot;Header&quot;">​</a></h3><ul><li>Judul: &quot;Rekap KM bulanan per truk&quot;</li><li>Subtitle: &quot;Data dihitung dari trip mileage Wialon pada bulan kalender yang dipilih&quot;</li><li>Badge: &quot;Cache aktif&quot; atau &quot;Data terbaru&quot;</li></ul><h3 id="filter-1" tabindex="-1">Filter <a class="header-anchor" href="#filter-1" aria-label="Permalink to &quot;Filter&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Deskripsi</th></tr></thead><tbody><tr><td>Bulan</td><td>Pilih periode (format YYYY-MM)</td></tr><tr><td>Pencarian</td><td>Cari: plat / kendaraan / unit Wialon</td></tr></tbody></table><p>Tombol: <strong>Export Excel</strong>, <strong>Tampilkan</strong>, link <strong>Lokasi Truk</strong>.</p><h3 id="summary-cards" tabindex="-1">Summary Cards <a class="header-anchor" href="#summary-cards" aria-label="Permalink to &quot;Summary Cards&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Card</th><th>Deskripsi</th></tr></thead><tbody><tr><td>Total KM</td><td>Akumulasi kilometer trip pada periode terpilih</td></tr><tr><td>Truk Berjalan</td><td>Truk yang punya minimal 1 trip pada bulan ini</td></tr><tr><td>Total Trip</td><td>Jumlah trip Wialon yang terdeteksi</td></tr><tr><td>Truk Ditampilkan</td><td>Jumlah truck di tabel (+ info error data)</td></tr></tbody></table><h3 id="tabel-mileage" tabindex="-1">Tabel Mileage <a class="header-anchor" href="#tabel-mileage" aria-label="Permalink to &quot;Tabel Mileage&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kolom</th><th>Deskripsi</th></tr></thead><tbody><tr><td>No Truck</td><td>Plat nomor</td></tr><tr><td>Kendaraan</td><td>Jenis kendaraan</td></tr><tr><td>Total KM</td><td>Jarak tempuh bulan itu</td></tr><tr><td>Trip</td><td>Jumlah trip</td></tr><tr><td>Trip Pertama</td><td>Waktu trip pertama dalam bulan</td></tr><tr><td>Trip Terakhir</td><td>Waktu trip terakhir dalam bulan</td></tr><tr><td>Status</td><td>has_trip / no_trip / unlinked / invalid_mapping / error</td></tr></tbody></table><h3 id="status-mileage" tabindex="-1">Status Mileage <a class="header-anchor" href="#status-mileage" aria-label="Permalink to &quot;Status Mileage&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Arti</th></tr></thead><tbody><tr><td>has_trip</td><td>Ada data trip, KM terhitung</td></tr><tr><td>no_trip</td><td>GPS terhubung tapi tidak ada trip di bulan ini</td></tr><tr><td>unlinked</td><td>Truck belum punya mapping Wialon</td></tr><tr><td>invalid_mapping</td><td>Wialon unit ID tidak valid di Wialon</td></tr><tr><td>error</td><td>Gagal mengambil data dari Wialon</td></tr></tbody></table><h3 id="export-excel" tabindex="-1">Export Excel <a class="header-anchor" href="#export-excel" aria-label="Permalink to &quot;Export Excel&quot;">​</a></h3><p>Klik <strong>Export Excel</strong> untuk download data mileage dalam format <code>.xlsx</code> sesuai filter aktif.</p><h3 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h3><p>Pilihan rows per page + navigasi halaman.</p><hr><h2 id="akses-berdasarkan-role" tabindex="-1">Akses Berdasarkan Role <a class="header-anchor" href="#akses-berdasarkan-role" aria-label="Permalink to &quot;Akses Berdasarkan Role&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Halaman</th><th style="text-align:center;">Admin</th><th style="text-align:center;">User</th><th style="text-align:center;">Mekanik</th><th style="text-align:center;">CS</th></tr></thead><tbody><tr><td>Home (Dashboard)</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td></tr><tr><td>Schedule Pengiriman</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td>Monitoring Kendaraan</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td></tr><tr><td>Lokasi Truk</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td></tr><tr><td>KM Bulanan Truk</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td></tr></tbody></table>',108)])])}const c=t(n,[["render",d]]);export{p as __pageData,c as default};
